const genericUnionContract = `
type Age = Int where it >= 0 @code "age.nonnegative"
data Choice a = None | One a | Pair a a | Optional (Maybe a)
selected :: Choice a -> Bool
selected None = False
selected _ = True
type Selected a = Choice a where selected it @code "choice.selected"
type Lists a = Selected [a]
type AgeLists = Lists Age
data Tree a = Leaf a | Branch (Tree a) (Tree a)
data RefinedArg a = Value (a where show it /= "0" @code "argument.nonzero")
data Either a b = Left a | Right b | Both a b
type Swap a b = Either b a
type Same a = Swap a a
type FixedEither = Swap Age Int
data Mono = Mark Int
type PhantomUnion a = Mono
type AgePhantom = PhantomUnion Age
data GenericCollision a = Factory a | Variant a | Draft a | Data a
type Wrapped = { choice :: Choice Age, tree :: Tree Age, refined :: RefinedArg Int }
`

func TestGenericUnionWitnessArityLimit(t *testing.T) {
	parameters := []string{}
	for i := 0; i < 251; i++ {
		parameters = append(parameters, fmt.Sprintf("t%d", i))
	}
	program, err := language.Compile("data TooMany " + strings.Join(parameters, " ") + " = Empty\n")
	if err != nil {
		t.Fatal(err)
	}
	if _, err = GenerateModels(program, "example.toomany", "Contract"); err == nil || !strings.Contains(err.Error(), "witness arity exceeds JVM method limits") {
		t.Fatalf("expected bounded generic-union witness rejection, got %v", err)
	}
}

