const genericUnionProofJava = `
package example.genericunions;
import java.math.BigInteger;
import java.util.List;
public final class GenericUnionProof {
    static void rejects(Runnable action){try{action.run();throw new AssertionError("foreign evidence accepted");}catch(IllegalArgumentException expected){}}
    public static void run(){
        var age=ModelTypes.forAge();var integer=ModelTypes.integer();var raw=new Data.Variant("One",List.of(new Data.Number(Rational.ONE)));
        var selected=ModelSupport.validate(ModelTypes.forSelected(age),raw,Budget.Limits.defaults());new Choice.One<>(age,selected);new Selected.One<>(age,selected);
        rejects(()->new Choice.One<>(integer,selected));rejects(()->new Lists.One<>(age,selected));
        var listRaw=new Data.Variant("One",List.of(new Data.Sequence(List.of(new Data.Number(Rational.ONE)))));var closed=ModelSupport.validate(ModelTypes.forAgeLists(),listRaw,Budget.Limits.defaults());
        new Choice.One<>(ModelTypes.list(age),closed);new Selected.One<>(ModelTypes.list(age),closed);new Lists.One<>(age,closed);new AgeLists.One(closed);
        rejects(()->new Choice.One<>(ModelTypes.list(integer),closed));rejects(()->new Selected.One<>(age,closed));
    }
}
`

